def project_order(quantity,events):
    # Own normalized ONE-order/ONE-epoch model, not FIX OrdStatus or a venue adapter.
    kinds=("ACK","REJECT","FILL","CANCEL_REQUEST","CANCEL_ACK","CANCEL_REJECT")
    if type(quantity) is not int or not 1<=quantity<=100:
        raise ValueError("invalid order quantity")
    if type(events) is not list or len(events)>32:
        raise ValueError("invalid event list")
    for event in events:
        if type(event) is not tuple or len(event)!=3:
            raise ValueError("invalid event shape")
        event_id,kind,amount=event
        if type(event_id) is not int or not 1<=event_id<=10000 or type(kind) is not str or kind not in kinds or type(amount) is not int:
            raise ValueError("invalid event fields")
        if not (1<=amount<=100 if kind=="FILL" else amount==0):
            raise ValueError("invalid event amount")
    phase="submitted"
    filled=0
    cancel_pending=False # OUR local request flag, not a venue PendingCancel status
    seen={}
    for event in events:
        event_id,kind,amount=event
        if event_id in seen:
            if seen[event_id]!=event:raise ValueError("conflicting event identity")
            continue
        if kind=="ACK" and phase=="submitted":phase="working"
        elif kind=="REJECT" and phase=="submitted":phase="rejected"
        elif kind=="FILL" and phase=="working" and amount<=quantity-filled:
            filled+=amount
            if filled==quantity:phase="filled"
        elif kind=="CANCEL_REQUEST" and phase=="working" and not cancel_pending:
            cancel_pending=True
        elif kind=="CANCEL_ACK" and phase=="working" and cancel_pending:
            phase="canceled"
            cancel_pending=False
        elif kind=="CANCEL_REJECT" and phase in ("working","filled") and cancel_pending:
            cancel_pending=False
        else:raise ValueError("invalid order transition")
        seen[event_id]=event
    remaining=quantity-filled if phase in ("submitted","working") else 0
    unexecuted_closed=quantity-filled-remaining
    return phase,filled,remaining,unexecuted_closed,cancel_pending,tuple(seen)

history=[(1,"ACK",0),(2,"FILL",3),(3,"CANCEL_REQUEST",0),(4,"FILL",2),(5,"CANCEL_ACK",0)]
print(project_order(10,history))
print(project_order(10,history+[history[1]])==project_order(10,history))
late=[(1,"ACK",0),(2,"CANCEL_REQUEST",0),(3,"FILL",10),(4,"CANCEL_REJECT",0)]
print(project_order(10,late))
try:
    project_order(10,history+[(2,"FILL",4)])
except ValueError as error:
    print(error)
